"""EPIC protocol laboratory: replay / audit / export."""
import json
import re
import sys

MAX_LINE = 32 * 1024 * 1024
VMAX_SNAP = 1 << 60


class Err(Exception):
    def __init__(self, cat):
        Exception.__init__(self, cat)
        self.cat = cat


def isint(x):
    return isinstance(x, int) and not isinstance(x, bool)


def chk(cond, cat):
    if not cond:
        raise Err(cat)


NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,63}\Z")


def get_str_name(x):
    if not isinstance(x, str):
        raise Err("E_SCHEMA")
    if len(x) > 64:
        raise Err("E_LIMIT")
    if NAME_RE.match(x) is None:
        raise Err("E_SCHEMA")
    return x


def check_keys(obj, keys):
    chk(isinstance(obj, dict), "E_SCHEMA")
    if len(obj) != len(keys):
        raise Err("E_SCHEMA")
    for k in keys:
        chk(k in obj, "E_SCHEMA")


def check_vec(vec, D, lo, hi):
    chk(isinstance(vec, list), "E_SCHEMA")
    chk(len(vec) == D, "E_SCHEMA")
    for x in vec:
        if not isint(x):
            raise Err("E_SCHEMA")
        if x < lo or x > hi:
            raise Err("E_LIMIT")


def parse_inputs(v):
    """validated rectangular P x R x D array -> (P, R, D, data)"""
    chk(isinstance(v, list), "E_SCHEMA")
    P = len(v)
    if P < 1 or P > 8:
        raise Err("E_LIMIT")
    R = None
    D = None
    for row in v:
        chk(isinstance(row, list), "E_SCHEMA")
        if R is None:
            R = len(row)
        elif len(row) != R:
            raise Err("E_SCHEMA")
        if R > 128:
            raise Err("E_LIMIT")
    for row in v:
        for vec in row:
            chk(isinstance(vec, list), "E_SCHEMA")
            if D is None:
                D = len(vec)
            elif len(vec) != D:
                raise Err("E_SCHEMA")
            if D > 32:
                raise Err("E_LIMIT")
    if D is None:
        D = 0
    for row in v:
        for vec in row:
            for x in vec:
                if not isint(x):
                    raise Err("E_SCHEMA")
                if x < -1000000000 or x > 1000000000:
                    raise Err("E_LIMIT")
    return P, R, D, v


def expected_sums(inp, P, R, D):
    """expected[q] = sum over all ranks of inputs[r][q]"""
    out = []
    for q in range(R):
        s = [0] * D
        for r in range(P):
            vec = inp[r][q]
            for i in range(D):
                s[i] += vec[i]
        out.append(s)
    return out


def parse_op(v):
    chk(isinstance(v, str), "E_SCHEMA")
    if v not in ("replay", "audit", "export"):
        raise Err("E_SCHEMA")
    return v


def parse_events(v, P, R):
    chk(isinstance(v, list), "E_SCHEMA")
    if len(v) > 20000:
        raise Err("E_LIMIT")
    out = []
    for ev in v:
        chk(isinstance(ev, list), "E_SCHEMA")
        chk(len(ev) >= 1, "E_SCHEMA")
        k = ev[0]
        if not isinstance(k, str) or k not in ("send", "retry", "deliver", "drop", "duplicate"):
            raise Err("E_SCHEMA")
        if k == "send":
            chk(len(ev) == 3, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] < P, "E_LIMIT")
            if not isint(ev[2]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[2] < R, "E_LIMIT")
        elif k == "retry":
            chk(len(ev) == 2, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] < P, "E_LIMIT")
        else:
            chk(len(ev) == 2, "E_SCHEMA")
            if not isint(ev[1]):
                raise Err("E_SCHEMA")
            chk(0 <= ev[1] <= 200000, "E_LIMIT")
        out.append(ev)
    return out


def do_replay(inp, P, R, D, req):
    slotsn = req["slots"]
    window = req["window"]
    events = parse_events(req["events"], P, R)
    if not isint(slotsn):
        raise Err("E_SCHEMA")
    chk(1 <= slotsn <= 16, "E_LIMIT")
    if not isint(window):
        raise Err("E_SCHEMA")
    chk(1 <= window <= slotsn, "E_LIMIT")

    buf = [None] * slotsn

    class Ent:
        __slots__ = ("seq", "ranks", "sum")

        def __init__(self, seq):
            self.seq = seq
            self.ranks = set()
            self.sum = [0] * D

    floor = 0
    up_next = [0] * P
    acked = [0] * P
    sentv = [0] * P
    received = [[] for _ in range(P)]
    pending = {}
    total_created = 0
    max_pending = 0
    ev_status = []
    ev_created = []

    def new_packet(kind, rank, seq, value):
        nonlocal total_created
        if len(pending) >= 2048 or total_created >= 200000:
            raise Err("E_LIMIT")
        pid = total_created
        total_created += 1
        pending[pid] = [pid, kind, rank, seq, value]
        return pid

    for ev in events:
        k = ev[0]
        created = []
        if k == "send":
            r = ev[1]
            q = ev[2]
            lim = R
            if sentv[r] + window < lim:
                lim = sentv[r] + window
            if sentv[r] <= q < lim:
                pid = new_packet("up", r, q, list(inp[r][q]))
                created.append(pid)
                st = "ok"
            else:
                st = "disabled"
        elif k == "retry":
            r = ev[1]
            for e in buf:
                if e is not None and e.ranks and len(e.ranks) == P and e.seq >= acked[r]:
                    pid = new_packet("down", r, e.seq, list(e.sum))
                    created.append(pid)
            st = "ok"
        else:
            pid = ev[1]
            pkt = pending.pop(pid, None)
            if pkt is None:
                ev_status.append("missing")
                ev_created.append([])
                continue
            kind = pkt[1]
            r = pkt[2]
            q = pkt[3]
            if kind == "up":
                if floor <= q < floor + slotsn:
                    idx = q % slotsn
                    e = buf[idx]
                    if e is None or e.seq != q:
                        e = Ent(q)
                        buf[idx] = e
                    if r not in e.ranks:
                        vec = pkt[4]
                        s = e.sum
                        for i in range(D):
                            s[i] += vec[i]
                        e.ranks.add(r)
                        became_full = len(e.ranks) == P
                    else:
                        became_full = False
                    n = up_next[r]
                    while True:
                        e2 = buf[n % slotsn]
                        if e2 is not None and e2.seq == n and r in e2.ranks:
                            n += 1
                        else:
                            break
                    up_next[r] = n
                    created.append(new_packet("uack", r, n, None))
                    if became_full:
                        s = list(e.sum)
                        for t in range(P):
                            created.append(new_packet("down", t, q, s))
            elif kind == "uack":
                kk = pkt[3]
                if kk > sentv[r]:
                    sentv[r] = kk
            elif kind == "down":
                if q == len(received[r]):
                    received[r].append(pkt[4])
                created.append(new_packet("dack", r, len(received[r]), None))
            elif kind == "dack":
                kk = pkt[3]
                if kk > acked[r]:
                    acked[r] = kk
                    nf = min(acked)
                    if nf > floor:
                        floor = nf
                        for i in range(slotsn):
                            e = buf[i]
                            if e is not None and e.seq < floor:
                                buf[i] = None
            st = "ok"
        ev_status.append(st)
        ev_created.append(created)

    slot_list = []
    for i in range(slotsn):
        e = buf[i]
        if e is not None:
            slot_list.append({"seq": e.seq, "ranks": sorted(e.ranks), "sum": list(e.sum)})
    slot_list.sort(key=lambda x: x["seq"])
    packets = []
    for pid in range(total_created):
        p = pending.get(pid)
        if p is not None:
            packets.append({"id": p[0], "kind": p[1], "rank": p[2], "seq": p[3], "value": p[4]})
    hosts = [{"sent": sentv[r], "received": [list(v) for v in received[r]]} for r in range(P)]
    evout = [{"status": ev_status[i], "created": ev_created[i]} for i in range(len(events))]
    return {"hosts": hosts, "floor": floor, "slots": slot_list, "packets": packets, "events": evout}


def parse_edge(v, nstates):
    chk(isinstance(v, list), "E_SCHEMA")
    chk(len(v) == 3, "E_SCHEMA")
    if not isint(v[0]):
        raise Err("E_SCHEMA")
    chk(0 <= v[0] < nstates, "E_LIMIT")
    name = get_str_name(v[1])
    if not isint(v[2]):
        raise Err("E_SCHEMA")
    chk(0 <= v[2] < nstates, "E_LIMIT")
    return (v[0], name, v[2])


def parse_fairness(v):
    chk(isinstance(v, list), "E_SCHEMA")
    if len(v) > 16:
        raise Err("E_LIMIT")
    out = []
    seen = set()
    for f in v:
        check_keys(f, ("action", "mode"))
        chk(isinstance(f["mode"], str) and f["mode"] in ("weak", "strong"), "E_SCHEMA")
        a = get_str_name(f["action"])
        chk(a not in seen, "E_SCHEMA")
        seen.add(a)
        out.append((a, f["mode"]))
    return out


def parse_states(v, P, R, D):
    chk(isinstance(v, list), "E_SCHEMA")
    if len(v) < 1 or len(v) > 12000:
        raise Err("E_LIMIT")
    for f in v:
        check_keys(f, ("delivered", "slots"))
        dl = f["delivered"]
        chk(isinstance(dl, list), "E_SCHEMA")
        chk(len(dl) == P, "E_SCHEMA")
        for rank in dl:
            chk(isinstance(rank, list), "E_SCHEMA")
            if len(rank) > R:
                raise Err("E_LIMIT")
            for vec in rank:
                check_vec(vec, D, -VMAX_SNAP, VMAX_SNAP)
        sl = f["slots"]
        chk(isinstance(sl, list), "E_SCHEMA")
        if len(sl) > 16:
            raise Err("E_LIMIT")
        seqs = set()
        for s in sl:
            check_keys(s, ("seq", "ranks", "sum"))
            if not isint(s["seq"]):
                raise Err("E_SCHEMA")
            chk(0 <= s["seq"] < R, "E_LIMIT")
            chk(s["seq"] not in seqs, "E_SCHEMA")
            seqs.add(s["seq"])
            rk = s["ranks"]
            chk(isinstance(rk, list), "E_SCHEMA")
            rkset = set()
            for x in rk:
                if not isint(x):
                    raise Err("E_SCHEMA")
                chk(0 <= x < P, "E_LIMIT")
                chk(x not in rkset, "E_SCHEMA")
                rkset.add(x)
            check_vec(s["sum"], D, -VMAX_SNAP, VMAX_SNAP)


def parse_graph(inp, P, R, D, req):
    parse_states(req["states"], P, R, D)
    states = req["states"]
    n = len(states)
    edges = req["edges"]
    chk(isinstance(edges, list), "E_SCHEMA")
    if len(edges) > 60000:
        raise Err("E_LIMIT")
    elist = []
    names = set()
    seen_e = set()
    for e in edges:
        s, nm, t = parse_edge(e, n)
        key = (s, nm, t)
        chk(key not in seen_e, "E_SCHEMA")
        seen_e.add(key)
        names.add(nm)
        elist.append(key)
    fair = parse_fairness(req["fairness"])
    for a, m in fair:
        names.add(a)
    if len(names) > 64:
        raise Err("E_LIMIT")
    st = req["start"]
    if not isint(st):
        raise Err("E_SCHEMA")
    chk(0 <= st < n, "E_LIMIT")
    return states, elist, fair, names, st, n
